//! S1 of the behaviour carry-forward (workspace letter H23): **what a consumer can RELY ON**, which a
//! surface diff cannot see. A release that starts REFUSING a module the last one accepted changes no
//! API, yet breaks a working consumer.
//!
//! Every module of `tests/behaviour/` (generated by `scripts/behaviour-corpus.ts`, one minimal module
//! per feature) is judged under every configuration [`judge::configs`] names: decode and validate,
//! never run. The verdicts must equal `tests/behaviour-snapshot.txt`. A difference FAILS, classified
//! by the floor it sets (H23's rule):
//!
//! | change | floor |
//! | --- | --- |
//! | refused → accepted (a line ADDED) | minor |
//! | **accepted → refused (a line REMOVED)** | **MAJOR** (pre-1.0: a minor plus a Breaking Changes row, rule 6) |
//!
//! "Resolved" includes INTENDED: a correct new refusal is resolved by re-baselining in its OWN commit,
//! with the version and the CHANGELOG row it demands:
//!
//!     WASMRT_BEHAVIOUR_REBASELINE=1 cargo test -p wasmrt-core --test behaviour
//!
//! Against a past RELEASE (S1's floor at release time, and the inversion): `scripts/carry-forward.ts`.

#[path = "behaviour/judge.rs"]
mod judge;

use std::path::PathBuf;
use wasmrt_core::features::Feature;

fn repo() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("..").join("..")
}

fn table() -> Vec<(Feature, &'static str)> {
    Feature::ALL.iter().map(|&f| (f, f.name())).collect()
}

const SNAPSHOT: &str = "tests/behaviour-snapshot.txt";

#[test]
fn the_accepted_behaviour_is_carried_forward() {
    let corpus = judge::load_corpus(&repo().join("tests").join("behaviour"));
    assert!(corpus.len() >= 60, "the behaviour corpus is missing; run `bun scripts/behaviour-corpus.ts`");
    let now = judge::verdict_lines(&table(), &corpus);
    let path = repo().join(SNAPSHOT);

    if std::env::var_os("WASMRT_BEHAVIOUR_REBASELINE").is_some() {
        let header = "# S1 behaviour snapshot (letter H23): every (configuration, module) pair this tree ACCEPTS.\n\
                      # Judged by crates/wasmrt-core/tests/behaviour.rs over tests/behaviour/ (decode + validate, nothing runs).\n\
                      # Re-baseline ONLY in its own commit: WASMRT_BEHAVIOUR_REBASELINE=1 cargo test -p wasmrt-core --test behaviour\n";
        std::fs::write(&path, format!("{header}{}\n", now.join("\n"))).expect("write the snapshot");
        return;
    }

    let text = std::fs::read_to_string(&path).expect("read tests/behaviour-snapshot.txt");
    let recorded: Vec<&str> = text.lines().filter(|l| !l.starts_with('#') && !l.is_empty()).collect();
    let removed: Vec<&str> = recorded.iter().copied().filter(|l| !now.iter().any(|n| n == l)).collect();
    let added: Vec<&String> = now.iter().filter(|n| !recorded.contains(&n.as_str())).collect();
    if removed.is_empty() && added.is_empty() {
        return;
    }
    let mut report = String::new();
    if !removed.is_empty() {
        report.push_str(&format!(
            "\n{} ACCEPTED → REFUSED (accepting LESS) — floor: MAJOR (pre-1.0: minor + a Breaking Changes row):\n",
            removed.len()
        ));
        for l in removed.iter().take(40) {
            report.push_str(&format!("  - {l}\n"));
        }
    }
    if !added.is_empty() {
        report.push_str(&format!("\n{} REFUSED → ACCEPTED (accepting more) — floor: minor:\n", added.len()));
        for l in added.iter().take(40) {
            report.push_str(&format!("  + {l}\n"));
        }
    }
    panic!(
        "the accepted behaviour changed against {SNAPSHOT}.{report}\n\
         If the change is INTENDED, re-baseline in its own commit (with the version and CHANGELOG row \
         the floor demands): WASMRT_BEHAVIOUR_REBASELINE=1 cargo test -p wasmrt-core --test behaviour"
    );
}
